def minDeletionSize(A):
    if not A or not A[0]:
        return 0

    n = len(A)
    m = len(A[0])

    # Initialize the dp array where dp[i] represents the length of the longest
    # lexicographically sorted subsequence ending at column i
    dp = [1] * m

    # Fill the dp array
    for i in range(1, m):
        for j in range(i):
            # Check if all rows have A[row][j] <= A[row][i]
            if all(A[row][j] <= A[row][i] for row in range(n)):
                dp[i] = max(dp[i], dp[j] + 1)

    # The result is the total number of columns minus the length of the longest
    # lexicographically sorted subsequence
    return m - max(dp)
